-- Cronograma fisico-financeiro Smart Fit Cesar Lattes (gerado por scripts/cronograma-smartfit.mjs em 2026-09-03)
-- Fonte: 03. CRONOGRAMA FISICO FINANCEIRO.pdf (rev. contraproposta). Retencao 10%; mes 01 = junho/2026.
update project set starts_at = coalesce(starts_at, '2026-06-01'), contractual_end = coalesce(contractual_end, '2027-02-28'), target_margin = coalesce(target_margin, 0.25),
  scope = coalesce(nullif(scope,''), 'Execução da unidade Smart Fit em regime de empreitada global Turn Key') where code = 'OB-SF-CL-01';

-- os servicos SFCL-01..06 derivados da planilha sao substituidos (mesmo codigo) pelas etapas do cronograma;
-- as receitas "mao de obra" perdem o vinculo (nao ha etapa equivalente) e as demais sao religadas pelo nome abaixo
update financial_entry e set service_id = null where e.project_id = (select id from project where code = 'OB-SF-CL-01') and e.description ilike '%mão de obra%';
insert into project_service (organization_id, project_id, code, name, phase, unit, budgeted_qty, executed_qty, budgeted_cost, sale_price, sale_direct, budget_base, planned_start, planned_end, status, notes, active)
values ((select id from organization where code = 'EIFF'), (select id from project where code = 'OB-SF-CL-01'), 'SFCL-01', 'Projetos executivos', 'Projeto', 'vb', 1, 0, 0, 56700.00, 0.00, 63000, '2026-05-01', '2026-07-31', 'Não iniciado', 'Etapa do cronograma contratual: Projetos Executivos. Preço = faturamento da construtora líquido de retenção (10%).', true)
