-- religa as receitas previstas da planilha aos servicos do cronograma (pelo nome)
update financial_entry e set service_id = (select id from project_service where project_id = (select id from project where code = 'OB-SF-CL-01') and code = 'SFCL-06') where e.project_id = (select id from project where code = 'OB-SF-CL-01') and e.description ilike '%estrutura met%';
update financial_entry e set service_id = (select id from project_service where project_id = (select id from project where code = 'OB-SF-CL-01') and code = 'SFCL-13') where e.project_id = (select id from project where code = 'OB-SF-CL-01') and e.description ilike '%pintura%';
