update financial_entry e set service_id = (select id from project_service where project_id = (select id from project where code = 'OB-SF-CL-01') and code = 'SFCL-09') where e.project_id = (select id from project where code = 'OB-SF-CL-01') and e.description ilike '%steel deck%';
update financial_entry e set service_id = null where e.project_id = (select id from project where code = 'OB-SF-CL-01') and e.service_id in (select id from project_service where project_id = (select id from project where code = 'OB-SF-CL-01') and active = false);
